# ═══════════════════════════════════════════════════════════════════════════════════
# DATABASE MODULE - POSTGRESQL FLEXIBLE SERVER
# ═══════════════════════════════════════════════════════════════════════════════════

# Generate a random password for the PostgreSQL admin user
resource "random_password" "pg_admin_password" {
  length  = 32
  special = true
  upper   = true
  lower   = true
  numeric = true

  # Ensure password meets Azure PostgreSQL requirements
  min_upper   = 1
  min_lower   = 1
  min_numeric = 1
  min_special = 1
}

resource "azurerm_postgresql_flexible_server" "postgres" {
  name                   = var.pg_server_name
  resource_group_name    = var.resource_group_name
  location               = var.location
  version                = var.pg_version
  administrator_login    = var.pg_admin_username
  administrator_password = REDACTED

  sku_name   = var.pg_sku
  storage_mb = var.pg_storage * 1024

  public_network_access_enabled = true
  lifecycle {
    ignore_changes = [
      zone,
      high_availability[0].standby_availability_zone
    ]
    prevent_destroy = false
  }

  tags = {
    Environment = var.environment
    Project     = var.project
    Purpose     = "database"
  }
}

# One database per app in apps.yaml, keyed by app name.
resource "azurerm_postgresql_flexible_server_database" "database" {
  for_each = var.databases

  name      = each.value
  server_id = azurerm_postgresql_flexible_server.postgres.id
  collation = "en_US.utf8"
  charset   = "utf8"

  # Removing an app from apps.yaml must not drop its data.
  lifecycle {
    prevent_destroy = true
  }
}

# Firewall rule to allow all Azure services
resource "azurerm_postgresql_flexible_server_firewall_rule" "azure_services" {
  name             = "AllowAllAzureServices"
  server_id        = azurerm_postgresql_flexible_server.postgres.id
  start_ip_address = "0.0.0.0"
  end_ip_address   = "0.0.0.0"
}

# # Firewall rule to allow all IPs (for development/testing)
# resource "azurerm_postgresql_flexible_server_firewall_rule" "all_ips" {
#   name             = "AllowAllIPs"
#   server_id        = azurerm_postgresql_flexible_server.postgres.id
#   start_ip_address = "0.0.0.0"
#   end_ip_address   = "255.255.255.255"
# }

# Configure shared_preload_libraries for extensions
resource "azurerm_postgresql_flexible_server_configuration" "shared_preload_libraries" {
  name      = "azure.extensions"
  server_id = azurerm_postgresql_flexible_server.postgres.id
  value     = "VECTOR,PG_CRON,UUID-OSSP"
}

# Configure cron database name
resource "azurerm_postgresql_flexible_server_configuration" "cron_database_name" {
  name      = "cron.database_name"
  server_id = azurerm_postgresql_flexible_server.postgres.id
  value     = var.cron_database_name
}

# Enable autovacuum diagnostics metrics
resource "azurerm_postgresql_flexible_server_configuration" "autovacuum_diagnostics" {
  name      = "metrics.autovacuum_diagnostics"
  server_id = azurerm_postgresql_flexible_server.postgres.id
  value     = "on"
}
# ═══════════════════════════════════════════════════════════════════════════════════
# DATABASE MODULE VARIABLES
# ═══════════════════════════════════════════════════════════════════════════════════

variable "pg_server_name" {
  type        = string
  description = "PostgreSQL server name"
}

variable "resource_group_name" {
  type        = string
  description = "Resource group name for the PostgreSQL server"
}

variable "location" {
  type        = string
  description = "Azure region for the PostgreSQL server"
}

variable "pg_version" {
  type        = string
  description = "PostgreSQL version"
}

variable "pg_admin_username" {
  type        = string
  description = "PostgreSQL admin username"
}

variable "pg_sku" {
  type        = string
  description = "PostgreSQL server SKU"
}

variable "pg_storage" {
  type        = number
  description = "PostgreSQL storage size in GB"
}

variable "databases" {
  type        = map(string)
  description = "Database name per app (key: app name from apps.yaml)"

  validation {
