# APP REGISTRATION MODULE - AZURE AD APPLICATION REGISTRATION
# ═══════════════════════════════════════════════════════════════════════════════════
# This module creates an Azure AD App Registration for OAuth authentication

# Get current client (tenant) data
data "azuread_client_config" "current" {}

# Validation: Ensure required IDs are provided when using existing app registration
resource "null_resource" "validate_existing_app_ids" {
  count = !var.create_app_registration && var.app_registration_app_id == null ? 1 : 0

  provisioner "local-exec" {
    command = "echo 'ERROR: app_registration_app_id is required when create_app_registration is false' && exit 1"
  }
}

# Data source for existing application (if not creating new)
data "azuread_application" "existing" {
  count     = var.create_app_registration ? 0 : 1
  client_id = var.app_registration_app_id
}

# Data source for existing service principal (if not creating new)
# Note: Using client_id (application ID) instead of object_id for better reliability
data "azuread_service_principal" "existing" {
  count     = var.create_app_registration ? 0 : 1
  client_id = var.app_registration_app_id
}

# Create the App Registration
resource "azuread_application" "app_registration" {
  count                          = var.create_app_registration ? 1 : 0
  display_name                   = "${var.display_name}-${var.environment}"
  description                    = "OAuth App Registration for KnowledgeAI Admin ${var.environment} environment"
  sign_in_audience               = var.sign_in_audience
  fallback_public_client_enabled = true
  tags                           = var.tags

  # Web application configuration
  web {
    logout_url    = var.logout_url != "" ? var.logout_url : null
    redirect_uris = var.redirect_uris

    implicit_grant {
      access_token_issuance_enabled = var.enable_implicit_grant
      id_token_issuance_enabled     = var.enable_implicit_grant
    }
  }

  # Required resource access (Microsoft Graph permissions)
  required_resource_access {
    resource_app_id = "00000003-0000-0000-c000-000000000000" # Microsoft Graph

    resource_access {
      id   = "e1fe6dd8-ba31-4d61-89e7-88639da4683d" # User.Read
      type = "Scope"
    }

    resource_access {
      id   = "64a6cdd6-aab1-4aaf-94b8-3cc8405e90d0" # email
      type = "Scope"
    }

    resource_access {
      id   = "37f7f235-527c-4136-accd-4a02d197296e" # openid
      type = "Scope"
    }

    resource_access {
      id   = "14dad69e-099b-42c9-810b-d002981feec1" # profile
      type = "Scope"
    }
  }

  # Prevent destruction of the app registration
  lifecycle {
    ignore_changes = [tags]
  }
}

# Create password credential (client secret)
resource "azuread_application_password" "app_registration_password" {
  count          = var.create_app_registration ? 1 : 0
  application_id = azuread_application.app_registration[0].id
  display_name   = var.client_secret_display_name
  end_date       = timeadd(timestamp(), var.client_secret_end_date_relative)

  lifecycle {
    ignore_changes = [end_date]
  }
}

# Create service principal for the application - REQUIRED for federated credentials
resource "azuread_service_principal" "app_service_principal" {
  count                        = var.create_app_registration ? 1 : 0
  client_id                    = azuread_application.app_registration[0].client_id
  app_role_assignment_required = false
  owners                       = [data.azuread_client_config.current.object_id]

  tags = var.tags
}

# Create federated credentials for GitHub Actions OIDC
resource "azuread_application_federated_identity_credential" "federated_credentials" {
  count          = var.create_app_registration ? length(var.federated_credentials) : 0
  application_id = azuread_application.app_registration[0].id
  display_name   = var.federated_credentials[count.index].name
  description    = var.federated_credentials[count.index].description
  audiences      = var.federated_credentials[count.index].audiences
  issuer         = var.federated_credentials[count.index].issuer
  subject        = var.federated_credentials[count.index].subject

  depends_on = [azuread_application.app_registration, azuread_service_principal.app_service_principal]
}
