run "one_database_per_app" {
  command = plan

  assert {
    condition     = module.database.database_names == { "knowledgeai-admin" = "knowledgeai_admin", "alloq" = "alloq" }
    error_message = "Expected one database per app, named from apps.yaml (Admin keeps knowledgeai_admin)."
  }
}

run "secrets_from_apps_yaml" {
  command = plan

  assert {
    condition     = toset(output.secret_names.db) == toset(["avui-db-host", "avui-db-name", "avui-db-password", "avui-db-user", "alloq-db-host", "alloq-db-name", "alloq-db-password", "alloq-db-user"])
    error_message = "Expected the four <keyvault_prefix>-db-* secrets per app."
  }

  assert {
    condition     = contains(output.secret_names.seeded, "avui-confluence-token") && contains(output.secret_names.seeded, "common-db-encryption-key")
    error_message = "Every config_secrets name must exist in Key Vault."
  }

  assert {
    condition     = contains(output.secret_names.managed, "common-oauth-azure-client-id") && !contains(output.secret_names.seeded, "common-oauth-azure-client-id")
    error_message = "Secrets Terraform knows must be managed, not seeded."
  }

  assert {
    condition = alltrue([
      for n in ["common-ai-foundry-apikey", "common-ai-foundry-endpoint"] :
      contains(output.secret_names.managed, n)
    ])
    error_message = "The AI Foundry secrets must exist once as managed common-* secrets."
  }

  assert {
    condition     = length([for n in output.secret_names.seeded : n if n == "common-db-encryption-key"]) == 1
    error_message = "A common-* secret exists once for the platform, whatever the apps list."
  }
}

run "new_app_only_in_apps_yaml" {
  command = plan

  variables {
    apps_file = "tests/fixtures/apps_three.yaml"
  }

  assert {
    condition     = module.database.database_names["third"] == "third_db"
    error_message = "A new app in apps.yaml must get its database."
  }

  assert {
    condition     = contains(output.secret_names.db, "th-db-password") && contains(output.secret_names.seeded, "th-api-key")
    error_message = "A new app in apps.yaml must get its db and config secrets."
  }
}

