}

# With only knowledgeai-admin in apps.yaml (and its original secret names) the
# infrastructure is the one of the original KnowledgeAI-Admin repository without
# the email service: one database, the same Key Vault secrets without avui-acs-*,
# filled the same way.
run "admin_only_matches_original_repository" {
  command = plan

  variables {
    apps_file = "tests/fixtures/apps_admin_only.yaml"
    # The common-* secrets are an addition of the platform; without them the
    # secrets are the ones of the original repository.
    common_secret_names = []
  }

  assert {
    condition     = module.database.database_names == { "knowledgeai-admin" = "knowledgeai_admin" }
    error_message = "Admin only: expected the single original database."
  }

  assert {
    condition = toset(concat(output.secret_names.db, output.secret_names.managed, output.secret_names.seeded)) == toset([
      "avui-db-host", "avui-db-name", "avui-db-user", "avui-db-password",
      "avui-avvia-tenant-key-1", "avui-avvia-tenant-key-2", "avui-azure-api-endpoint", "avui-azure-api-key", "avui-blackforestlabs-api-key", "avui-confluence-token", "avui-confluence-user", "avui-db-encryption-key", "avui-github-app-id", "avui-github-installation-id", "avui-google-api-key", "avui-markdown-api-key", "avui-oauth-azure-client-id", "avui-oauth-azure-client-secret", "avui-oauth-azure-tenant-id", "avui-oauth-github-client-id", "avui-oauth-github-client-secret", "avui-perplexity-api-key", "avui-togetherai-api-key"
    ])
    error_message = "Admin only: expected exactly the Key Vault secrets of the original repository."
  }

  assert {
    condition = toset(output.secret_names.managed) == toset([
      "avui-oauth-azure-client-id", "avui-oauth-azure-client-secret", "avui-oauth-azure-tenant-id",
      "avui-azure-api-key", "avui-azure-api-endpoint",
    ])
    error_message = "Admin only: values from the app registration and AI Foundry must be written like in the original repository."
  }
}

run "no_workers_no_vm" {
  command = plan

  variables {
    apps_file = "tests/fixtures/apps_three.yaml"
  }

  assert {
    condition     = length(module.worker_vm) == 0 && module.vnet.worker_subnet_id == null
    error_message = "Without workers in apps.yaml there must be no worker subnet and no VM."
  }
}

run "worker_vm_from_apps_yaml" {
  command = plan

  variables {
    apps_file = "tests/fixtures/apps_workers.yaml"
  }

  # The login server is only known after an apply.
  override_module {
    target          = module.acr
    override_during = plan
    outputs = {
      acr_id           = "/subscriptions/00000000-0000-0000-0000-000000000000/resourceGroups/rg/providers/Microsoft.ContainerRegistry/registries/knaitest"
      acr_name         = "knaitest"
      acr_login_server = "knaitest.azurecr.io"
    }
  }

  assert {
    condition     = keys(module.worker_vm) == ["knowledgeai-admin-strix-runner"]
    error_message = "One VM per worker, named <app>-<worker>."
  }

  assert {
    condition     = module.worker_vm["knowledgeai-admin-strix-runner"].vm_name == "knowledgeai-admin-strix-runner"
    error_message = "The VM name must be <app>-<worker>; the deploy workflow relies on it."
  }

  assert {
    condition = toset(module.worker_vm["knowledgeai-admin-strix-runner"].env_secrets) == toset(concat(
      ["avui-db-host", "avui-db-name", "avui-db-password", "avui-db-user"],
      var.common_secret_names,
      ["avui-confluence-token", "avui-runner-token"],
    ))
    error_message = "The container gets the app's secrets and its own extra secrets as env variables, nothing else."
  }

  assert {
    condition     = contains(output.secret_names.seeded, "avui-runner-token") && !anytrue([for n in output.secret_names.seeded : endswith(n, "-image")])
    error_message = "Extra worker secrets must exist as seeded Key Vault secrets; the image is no secret."
  }

  assert {
    condition     = module.worker_vm["knowledgeai-admin-strix-runner"].database_firewall_rule == "worker-knowledgeai-admin-strix-runner"
    error_message = "A worker with a public IP must get a PostgreSQL firewall rule."
  }

  assert {
    condition     = local.workers["knowledgeai-admin-strix-runner"].image == "knaitest.azurecr.io/knowledgeai-strix-runner:prod"
    error_message = "The VM runs the deploy tag prod of its repository in the ACR."
  }

  assert {
    condition     = !contains(output.secret_names.seeded, "avui-db-host") && contains(output.secret_names.managed, "common-ai-foundry-apikey")
    error_message = "Existing db-* and managed secrets are reused, not created again as seeded secrets."
  }

  assert {
    condition     = length([for n in output.secret_names.seeded : n if n == "common-db-encryption-key"]) == 1
    error_message = "A common secret used by a worker must still exist only once."
  }
}

run "worker_reads_the_whole_vault" {
  command = plan

  variables {
    apps_file = "tests/fixtures/apps_workers.yaml"
  }

  # The vault ID is only known after an apply.
  override_resource {
    target          = module.keyvault.azurerm_key_vault.kv
    override_during = plan
    values = {
      id = "/subscriptions/00000000-0000-0000-0000-000000000000/resourceGroups/rg/providers/Microsoft.KeyVault/vaults/knaitest"
