  }

  assert {
    condition     = module.worker_vm["knowledgeai-admin-strix-runner"].keyvault_reader_scope == "/subscriptions/00000000-0000-0000-0000-000000000000/resourceGroups/rg/providers/Microsoft.KeyVault/vaults/knaitest"
    error_message = "The worker identity must read the whole Key Vault, not only its own secrets."
  }
}

